import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { apiClient } from '@/shared/api-client/apiClient';

// Mirrors backend EventResponse / CreateEventRequest exactly. source is
// 'MANUAL' for user-created events; anything else (e.g. 'STUDY_PLAN') is
// generated by another module and the backend rejects edits/deletes on it.
export interface EventResponse {
  id: string;
  title: string;
  description: string | null;
  startAt: string;
  endAt: string | null;
  source: string;
}

export interface CreateEventPayload {
  title: string;
  description?: string;
  startAt: string;
  endAt?: string;
}

// Prefix shared by every month window, so mutations refresh whichever month is shown.
const EVENTS_QUERY_KEY = ['events'];

export function useEvents(from: string, to: string) {
  return useQuery({
    queryKey: [...EVENTS_QUERY_KEY, from, to],
    queryFn: () =>
      apiClient.get<EventResponse[]>(
        `/api/v1/events?from=${encodeURIComponent(from)}&to=${encodeURIComponent(to)}`,
      ),
  });
}

export function useCreateEvent() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (payload: CreateEventPayload) =>
      apiClient.post<EventResponse>('/api/v1/events', payload),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: EVENTS_QUERY_KEY }),
  });
}

export function useDeleteEvent() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (id: string) => apiClient.delete<void>(`/api/v1/events/${id}`),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: EVENTS_QUERY_KEY }),
  });
}
